INSERT INTO "public"."hospitals" ("id", "slug", "name", "short_name", "license_group", "page_path", "hero_title", "hero_subtitle", "hero_image_url", "overview_title", "overview_body", "quote", "offer_heading", "offer_title", "offer_body", "phone", "email_primary", "email_secondary", "location_text", "facebook_url", "facebook_label", "map_embed_url", "map_link_url", "card_description", "sort_order", "is_featured", "created_at", "updated_at") VALUES
	('adfdd6d2-05df-4693-a5e5-26b1fda43056', 'canch', 'Candijay Community Hospital', 'CanCH', 'Infirmaries', 'hospital-canch.html', 'Candijay Community Hospital', 'Poblacion, Candijay, Bohol', 'assets/hospitals/canch/canch_hero.png', 'Welcome to CanCH', 'Candijay Community Hospital (CanCH) is an Infirmary Hospital committed to delivering accessible and quality primary healthcare services to the people of Candijay and its neighboring municipalities in eastern Bohol. Operated under the Bohol Provincial Health Office (PHO), CanCH provides essential inpatient and outpatient medical services, general consultations, and basic diagnostics.', '', 'We Offer:', 'Infirmary Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, minor surgery, isolation facilities, maternity, and basic clinical laboratory.', '(038) 523-0022', 'candijayhospital2@gmail.com', 'provincialhealthoffice@gmail.com', 'Poblacion, Candijay, Bohol', '', '', 'https://maps.google.com/maps?q=9.851900,124.577200&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 60, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:53:49.391619+00'),
	('d98ef878-4088-41ce-85e7-4a4304b7dbfa', 'csgtmh', 'Cong. Simeon G. Toribio Memorial Hospital', 'CSGTMH', 'DOH-Licensed Level I Hospitals', 'hospital-csgtmh.html', 'Cong. Simeon G. Toribio Memorial Hospital', 'Carmen, Bohol', 'assets/hospitals/csgtmh/carmen.png', 'Welcome to CSGTMH', 'Cong. Simeon G. Toribio Memorial Hospital (CSGTMH) is a primary-level district health facility located in Poblacion, Carmen, Bohol. Managed and operated under the Bohol Provincial Health Office (PHO), CSGTMH is dedicated to providing high-quality, compassionate, and accessible inpatient and outpatient healthcare services to the communities of central Bohol.', '"Sa PHO, Una ang Serbisyo!"', 'We Offer:', 'DOH-Licensed Level I Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, surgery, isolation facilities, maternity, secondary clinical laboratory, and 1st level X-ray.', '(038) 525-9247', 'carmenhospital68@yahoo.com', 'provincialhealthoffice@gmail.com', 'Poblacion, Carmen, Bohol', 'https://www.facebook.com/profile.php?id=61583326373605', 'Simeon G. Toribio Hospital', 'https://maps.google.com/maps?q=9.8201335,124.1934452&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 50, false, '2026-08-03 06:01:58.423718+00', '2026-08-05 06:29:45.08558+00'),
	('324446de-b73e-4d80-9808-cf922015153b', 'gmph', 'Garcia Memorial Provincial Hospital', 'GMPH', 'DOH-Licensed Level II Hospital', 'hospital-gmph.html', 'Garcia Memorial Provincial Hospital', 'Talibon, Bohol', 'assets/hospitals/gmph/talibon.png', 'Welcome to GMPH', 'Garcia Memorial Provincial Hospital (GMPH) is a secondary-level health facility dedicated to serving the communities of northern and eastern Bohol. Under the Bohol Provincial Health Office (PHO), GMPH operates with a commitment to providing accessible, high-quality, and patient-centered medical care to every individual.', '"Sa PHO, Una ang Serbisyo!"', 'We Offer:', 'DOH-Licensed Level II Hospital', 'A departmentalized hospital providing clinical services including medicine, pediatrics, OB-GYN, surgery, ICU, NICU, tertiary clinical laboratory, and 2nd level X-ray.', '+63 38 515-5081', 'gmph.bohol2012@gmail.com', 'provincialhealthoffice@gmail.com', 'San Jose, Talibon, Bohol', 'https://www.facebook.com/gmph.talibon', 'Garcia Memorial Provincial Hospital', 'https://maps.google.com/maps?q=10.131240,124.318849&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 10, true, '2026-08-03 06:01:58.423718+00', '2026-08-03 07:13:15.563156+00'),
	('7e01bc0b-0bc9-4f13-a58e-8a68743eba70', 'cdh', 'Catigbian District Hospital', 'CDH', 'DOH-Licensed Level I Hospitals', 'hospital-cdh.html', 'Catigbian District Hospital', 'Catigbian, Bohol', 'assets/hospitals/cdh/cdh_hero.png', 'Welcome to CDH', 'Catigbian District Hospital (CDH) is a DOH-Licensed Level I health facility dedicated to serving the municipality of Catigbian and its neighboring communities in Bohol. Operated under the Bohol Provincial Health Office (PHO), CDH is committed to delivering accessible, compassionate, and high-quality inpatient and outpatient healthcare services to all residents of the area.', '"Sa PHO, Una ang Serbisyo!"', 'We Offer:', 'DOH-Licensed Level I Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, surgery, isolation facilities, maternity, secondary clinical laboratory, and 1st level X-ray.', '(038) 507-3106 / (038) 460-2585', 'pho_bohol@yahoo.com', 'provincialhealthoffice@gmail.com', 'Catigbian, Bohol', 'https://www.facebook.com/CADISHOSP', 'Catigbian District Hospital', 'https://maps.google.com/maps?q=9.851206,123.99599&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 20, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:53:49.391619+00'),
	('47080dee-3d07-4da2-89a5-32875eab1297', 'fdmh', 'Francisco Dagohoy Municipal Hospital', 'FDMH', 'DOH-Licensed Level I Hospitals', 'hospital-fdmh.html', 'Francisco Dagohoy Municipal Hospital', 'Inabanga, Bohol', 'assets/hospitals/fdmh/fdmh_hero.png', 'Welcome to FDMH', 'Francisco Dagohoy Municipal Hospital (FDMH) is a DOH-Licensed Level I health facility committed to delivering accessible and quality healthcare services to the people of Inabanga and its neighboring municipalities in Bohol. Operated under the Bohol Provincial Health Office (PHO), FDMH provides a comprehensive range of inpatient and outpatient medical services, from general consultations and surgical operations to laboratory diagnostics and maternal care.', '', 'We Offer:', 'DOH-Licensed Level I Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, surgery, isolation facilities, maternity, secondary clinical laboratory, and 1st level X-ray.', '(038) 512-9013', 'fdmh85@yahoo.com', 'provincialhealthoffice@gmail.com', 'Cangmundo Rd., Inabanga, Bohol', '', '', 'https://maps.google.com/maps?q=10.028500,124.063600&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 30, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:53:49.391619+00'),
	('27bba3c3-ef99-49fb-a32f-b2c5309ddbdd', 'tbgdh', 'Teodoro B. Galagar District Hospital', 'TBGDH', 'DOH-Licensed Level I Hospitals', 'hospital-tbgdh.html', 'Teodoro B. Galagar District Hospital', 'Jagna, Bohol', 'assets/hospitals/tbgdh/jagna.png', 'Welcome to TBGDH', 'Teodoro B. Galagar District Hospital (TBGDH) is a primary-level health facility dedicated to serving the communities of southeastern Bohol. Operated under the Bohol Provincial Health Office (PHO), TBGDH is committed to delivering accessible, efficient, and compassionate healthcare to all residents of Jagna and its surrounding municipalities.', '"Sa PHO, Una ang Serbisyo!"', 'We Offer:', 'DOH-Licensed Level I Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, surgery, isolation facilities, maternity, secondary clinical laboratory, and 1st level X-ray.', '(038) 531-8107', 'pho_bohol@yahoo.com', 'provincialhealthoffice@gmail.com', 'Severo Salas St. Poblacion, Jagna, Bohol', 'https://www.facebook.com/tbgdh', 'Teodoro B. Galagar Hospital', 'https://maps.google.com/maps?q=9.6517557,124.3690621&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 40, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:53:49.391619+00'),
	('e141f445-f7eb-4068-a05e-1516d857cd56', 'cnpcmh', 'Cong. Natalio P. Castillo Memorial Hospital', 'CNPCMH', 'Infirmaries', 'hospital-cnpcmh.html', 'Cong. Natalio P. Castillo Memorial Hospital', 'Basac, Loon, Bohol', 'assets/hospitals/cnpcmh/cnpcmh_hero.png', 'Welcome to CNPCMH', 'Cong. Natalio P. Castillo Memorial Hospital (CNPCMH) is an Infirmary Hospital committed to delivering accessible and quality primary healthcare services to the people of Loon and its neighboring municipalities. Operated under the Bohol Provincial Health Office (PHO), CNPCMH provides essential inpatient and outpatient medical services, general consultations, and basic diagnostics.', '', 'We Offer:', 'Infirmary Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, minor surgery, isolation facilities, maternity, and basic clinical laboratory.', '(038) 505-9011', 'cncmh_loon@yahoo.com.ph', 'provincialhealthoffice@gmail.com', 'Basac, Loon, Bohol', '', '', 'https://maps.google.com/maps?q=9.799800,123.793800&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 70, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:53:49.391619+00'),
	('0205867f-0277-4e34-80ca-14d68b1d2249', 'clach', 'Clarin Community Hospital', 'ClaCH', 'Infirmaries', 'hospital-clach.html', 'Clarin Community Hospital', 'Poblacion Norte, Clarin, Bohol', 'assets/hospitals/clach/clach_hero.png', 'Welcome to ClaCH', 'Clarin Community Hospital (ClaCH) is an Infirmary Hospital committed to delivering accessible and quality primary healthcare services to the people of Clarin and neighboring coastal towns in northwestern Bohol. Operated under the Bohol Provincial Health Office (PHO), ClaCH provides essential inpatient and outpatient medical services, general consultations, and basic diagnostics.', '', 'We Offer:', 'Infirmary Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, minor surgery, isolation facilities, maternity, and basic clinical laboratory.', '(038) 509-9122', 'clachphilhealth@yahoo.com', 'provincialhealthoffice@gmail.com', 'Poblacion Norte, Clarin, Bohol', '', '', 'https://maps.google.com/maps?q=9.962600,124.022900&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 80, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:53:49.391619+00'),
	('d248ce59-d639-4334-9a3b-fbb82037c3cd', 'mch', 'Maribojoc Community Hospital', 'MCH', 'Infirmaries', 'hospital-mch.html', 'Maribojoc Community Hospital', 'Saug, Bayacabac, Maribojoc, Bohol', 'assets/hospitals/mch/mch_hero.png', 'Welcome to MCH', 'Maribojoc Community Hospital (MCH) is an Infirmary Hospital committed to delivering accessible and quality primary healthcare services to the people of Maribojoc and its neighboring municipalities. Operated under the Bohol Provincial Health Office (PHO), MCH provides essential inpatient and outpatient medical services, general consultations, and basic diagnostics.', '', 'We Offer:', 'Infirmary Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, minor surgery, isolation facilities, maternity, and basic clinical laboratory.', '(038) 504-9621', 'maribojochospital@yahoo.com', 'provincialhealthoffice@gmail.com', 'Saug, Bayacabac, Maribojoc, Bohol', '', '', 'https://maps.google.com/maps?q=9.742300,123.844100&t=&z=15&ie=UTF8&iwloc=&output=embed', '', NULL, 90, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:53:49.391619+00'),
	('5d90b8ff-a9e3-4398-a266-e4bf5c74a1fb', 'cpgmh', 'Pres. Carlos P. Garcia Municipal Hospital', 'PCPGMH', 'Infirmaries', 'hospital-cpgmh.html', 'Pres. Carlos P. Garcia Municipal Hospital', 'Poblacion, Pres. Carlos P. Garcia (Pitogo), Bohol', 'assets/hospitals/cpgmh/cpgmh_hero.png', 'Welcome to PCPGMH', 'Pres. Carlos P. Garcia Municipal Hospital (PCPGMH) is an Infirmary Hospital committed to delivering accessible and quality primary healthcare services to the island municipality of President Carlos P. Garcia (Pitogo) and its communities. Operated under the Bohol Provincial Health Office (PHO), PCPGMH provides essential inpatient and outpatient medical services, general consultations, and basic diagnostics.', '', 'We Offer:', 'Infirmary Hospital', 'Provides primary care including general medicine, pediatrics, OB-GYN, minor surgery, isolation facilities, maternity, and basic clinical laboratory.', '(038) 534-1234', 'pcpgmh1992@gmail.com', 'provincialhealthoffice@gmail.com', 'Poblacion, Pres. Carlos P. Garcia (Pitogo), Bohol', '', '', 'https://maps.google.com/maps?q=10.117200,124.512600&t=&z=15&ie=UTF8&iwloc=&output=embed', '', '', 100, false, '2026-08-03 06:01:58.423718+00', '2026-08-03 06:59:51.264607+00');
