INSERT INTO "public"."hospital_programs" ("id", "hospital_id", "title", "body", "badge", "is_covid", "sort_order", "created_at", "updated_at") VALUES
	('657d0e25-9493-40b3-9b37-410aedd45f79', '27bba3c3-ef99-49fb-a32f-b2c5309ddbdd', 'Hospital Major Activities', '["Successful ISO 9001:2015 Surveillance Audit maintenance.","Annual calibration of all medical equipment.","Enhanced staff capabilities through BLS and ACLS trainings.","3-month specialized training programs for Hemodialysis personnel.","HDC Building expansions and procurement of new equipment and IT networks.","Regular administrative upgrading including AC units and high-capacity copying systems.","Active environmental advocacy including local mangrove tree planting activities."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('bb5250d6-ecc4-40f9-975d-f7bd24d09870', '27bba3c3-ef99-49fb-a32f-b2c5309ddbdd', 'COVID-19 Response & Safety', '["COVID Ward capacity expanded to accommodate patient surges.","Active COVID-19 Vaccination Program conducted.","Formal DOH Licensing obtained for the Covid isolation facility.","Maintained isolated COVID Emergency Rooms and dedicated COVID OB-ER."]', '', true, 2, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('05517f85-1b2b-42b7-bd18-b0801072d833', '7e01bc0b-0bc9-4f13-a58e-8a68743eba70', 'Hospital Major Activities', '["Successful ISO 9001:2015 Surveillance Audit maintenance.","Annual calibration of all medical equipment to guarantee accuracy and safety.","Enhanced staff capabilities through Basic Life Support (BLS) and Advanced Cardiovascular Life Support (ACLS) trainings.","Regular procurement of medical supplies and hospital infrastructure improvements.","Active implementation of public health programs (TB DOTS, Immunization, Family Planning).","Continuous Mother-Baby Friendly Hospital initiatives for safe maternal care."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('54df1483-1c81-440e-a8c0-5014bead6cdd', '324446de-b73e-4d80-9808-cf922015153b', 'Hospital Major Activities', '["Successful ISO 9001:2015 Surveillance Audit maintenance.","Annual calibration of all medical equipment to guarantee accuracy and safety.","Enhanced staff capabilities through Basic Life Support (BLS) and Advanced Cardiovascular Life Support (ACLS) trainings.","3-month specialized training programs for Hemodialysis personnel (nurses, doctors, and technicians).","HDC Building expansions: procured new furniture, fixtures, office equipment, and IT networks.","Regular administrative upgrading, including purchasing air conditioning units and high-capacity copying systems.","Active environmental advocacy: Participated in local mangrove tree planting activities."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 07:13:16.573402+00'),
	('587de3be-99e2-4ce7-b200-c93b5cb79589', '324446de-b73e-4d80-9808-cf922015153b', 'COVID-19 Response & Safety', '["COVID Ward capacity increased from 14 beds to 24 beds to accommodate surges.","Vigorous COVID-19 Vaccination Program, performing 4,221 shots.","Formal DOH Licensing obtained for the Covid isolation facility, making it fully operational.","Maintained isolated COVID Emergency Rooms (Covid ER) and dedicated COVID delivery units (Covid OB-ER)."]', '', true, 2, '2026-08-03 06:53:49.391619+00', '2026-08-03 07:13:16.573402+00'),
	('7bc6baa4-0087-4e19-93d0-9dfc205a7d92', '7e01bc0b-0bc9-4f13-a58e-8a68743eba70', 'COVID-19 Response & Safety', '["Established and maintained COVID isolation ward and COVID Emergency Room.","Active COVID-19 Vaccination Program.","Implementation of strict infection control protocols hospital-wide.","Maintained dedicated COVID OB-ER for maternity patients."]', '', true, 2, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('9dec29aa-8540-4422-ae06-d0a617d52a90', '47080dee-3d07-4da2-89a5-32875eab1297', 'Hospital Major Activities', '["Successful ISO 9001:2015 Surveillance Audit maintenance.","Annual calibration of all medical equipment to guarantee accuracy and safety.","Enhanced staff capabilities through BLS and ACLS trainings.","Regular procurement of medical supplies and hospital infrastructure improvements.","Active implementation of public health programs (TB DOTS, Animal Bite Treatment, Immunization).","Continuous Mother-Baby Friendly Hospital initiatives for safe maternal care and deliveries."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('ea4fba2d-1333-4e75-b6e8-feb7dd7c8355', '47080dee-3d07-4da2-89a5-32875eab1297', 'COVID-19 Response & Safety', '["Established and maintained COVID isolation ward and COVID Emergency Room.","Active COVID-19 Vaccination Program conducted for community and staff.","Implemented strict infection prevention and control protocols throughout the hospital.","Maintained dedicated COVID OB-ER for safe maternity services during the pandemic."]', '', true, 2, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('1813e9df-d1f4-4f30-8bb8-4e2ea153bdcb', 'adfdd6d2-05df-4693-a5e5-26b1fda43056', 'Recent Accomplishments', '["Continuous provision of outpatient and inpatient services to the community.","Upgrading of isolation facilities and hospital wards for better patient care.","Implementation of public health programs including TB DOTS and Animal Bite Treatment.","Maintenance of Mother-Baby Friendly initiatives for safe maternal care and deliveries."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('c9b49be2-660f-4b45-9e98-b1f8e709b172', '0205867f-0277-4e34-80ca-14d68b1d2249', 'Recent Accomplishments', '["Continuous provision of outpatient and inpatient services to the community.","Upgrading of isolation facilities and hospital wards for better patient care.","Implementation of public health programs including TB DOTS and Animal Bite Treatment.","Maintenance of Mother-Baby Friendly initiatives for safe maternal care and deliveries."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('7e433765-55a7-40bf-bf7b-cb213743c344', 'e141f445-f7eb-4068-a05e-1516d857cd56', 'Recent Accomplishments', '["Continuous provision of outpatient and inpatient services to the community.","Upgrading of isolation facilities and hospital wards for better patient care.","Implementation of public health programs including TB DOTS and Animal Bite Treatment.","Maintenance of Mother-Baby Friendly initiatives for safe maternal care and deliveries."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('e00deb4c-88f0-413d-b392-3f069f5761f0', 'd248ce59-d639-4334-9a3b-fbb82037c3cd', 'Recent Accomplishments', '["Continuous provision of outpatient and inpatient services to the community.","Upgrading of isolation facilities and hospital wards for better patient care.","Implementation of public health programs including TB DOTS and Animal Bite Treatment.","Maintenance of Mother-Baby Friendly initiatives for safe maternal care and deliveries."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
	('c81a4729-84a0-45cc-a2f1-6e96e0ce1bed', '5d90b8ff-a9e3-4398-a266-e4bf5c74a1fb', 'Recent Accomplishments', '["Continuous provision of outpatient and inpatient services to the island community.","Upgrading of isolation facilities and hospital wards for better patient care.","Implementation of public health programs including TB DOTS and Animal Bite Treatment.","Maintenance of Mother-Baby Friendly initiatives for safe maternal care and deliveries."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:59:10.399743+00'),
	('a322bc9b-833d-4292-b09f-731fc8449399', 'd98ef878-4088-41ce-85e7-4a4304b7dbfa', 'Key Infrastructure & Equipment Upgrades', '["Construction of Perimeter Fence — 90% completed to guarantee safety and security.","Sewage Treatment Setup — 50% completed biological sewage treatment setup.","Construction of Hemodialysis Center — 15% ongoing infrastructure development.","Procurement of Medical Equipment — Fully functional diagnostic and surgical units including portable X-ray machine with digitalization, CTG machine, ECG machine, cardiac monitors, defibrillators with monitors, LED OR lights, OR/DR tables, hemoglobin/hematocrit machines, infusion pumps, desktop computers, air conditioning inverters, and CCTV systems."]', '', false, 1, '2026-08-03 06:53:49.391619+00', '2026-08-05 06:29:45.798454+00');
