	('b1d0b848-ab78-4acb-9404-37944fb53aca', '27bba3c3-ef99-49fb-a32f-b2c5309ddbdd', 'Outpatient Department (OPD)', '', '["General Consultation", "Minor surgery operations (excision of cyst/mass, incision and drainage, dilation and curettage)", "OPD minor procedures (wound dressing, catheter insertion)", "OPD special area (Heart Station, ECG)", "Animal Bite Treatment Center (ABTC)", "TB DOTS Clinic (utilizing GeneXpert Machine for TB detection)", "Dental Services (tooth extraction, dental cleaning, tooth filling) — Suspended due to covid pandemic", "Family Planning and Prenatal Services", "Newborn Hearing Screening", "Anti-tetanus injections"]', 1, '2026-08-03 06:53:49.391619+00', '2026-08-03 06:53:49.391619+00'),
