	('ba08a16a-fe92-49af-802e-93807936c5b3', '324446de-b73e-4d80-9808-cf922015153b', 'Laboratory Section & Blood Bank', '', '["Comprehensive Clinical Pathology Services", {"items": ["FBS / RBS", "Blood Uric Acid", "Creatinine", "SGOT / SGPT", "Lipid Panel (Total Cholesterol, Triglycerides, HDL, LDL, VLDL)", "BUN", "HBA1C", "Alkaline Phosphatase", "Electrolytes (Sodium / Potassium)", "OGTT", "Cardiac Panel & Troponin I"], "title": "Clinical Chemistry & Panels"}, {"items": ["Complete Blood Count (CBC)", "Platelet Count", "White Blood Count", "Differential Count", "Hematocrit & Hemoglobin", "Red Blood Count", "Clotting Time & Bleeding Time", "Prothrombin Time & APTT"], "title": "Hematology & Coagulation"}, {"items": ["Urinalysis & Stool Exam", "Pregnancy Test", "Spermatozoa Detection", "HBsAG & Anti HCV", "Dengue Check / Dengue Duo / NS1 Ag", "Hepatitis A Virus Test (HAV IgG/IgM)", "Salmonella Typhi & H-Pylori", "HIV Antibody Test", "NCov Rapid Test & Swab (RT-PCR)", "Acid Fast Staining", "Occult Blood", "Syphilis Screen"], "title": "Immunology, Serology & Microscopy"}, {"items": ["Blood Typing & RH Typing", "Crossmatching", "Newborn Screening"], "title": "Blood Bank Services"}]', 2, '2026-08-03 06:53:49.391619+00', '2026-08-03 07:13:16.330168+00'),
	('ddbf1b5a-8ec1-426c-9362-54b8e6b9ef32', '324446de-b73e-4d80-9808-cf922015153b', 'Inpatient Wards & Nursing Wards', '', '["Admissions & Multi-disciplinary Inpatient Care", {"items": ["Female Surgical Ward & Male Surgical Ward", "General IM (Internal Medicine) Ward Male & Female", "Cardio / Cardiovascular Disease Ward", "Closely Monitored Patient (CMP) Ward", "Gastro Ward for Male & Female", "Adult Pulmo & Respiratory Therapy Room", "Infectious Ward & Isolation Ward", "Trans-Out Patient Ward", "General ICU (License application pending)"], "title": "General & Specialized Wards"}, {"items": ["Pediatric Non-Infectious Ward", "Pediatric Gastro Ward", "Pediatric Pulmonary Ward", "Pediatric CMP Ward & Pedia/Neonatal Ward", "Burn Unit"], "title": "Pediatric Wards"}, {"items": ["Covid Emergency Room (Covid ER) & Covid OB-ER", "COVID Ward (14-bed capacity, expanding to 22 beds)"], "title": "COVID-19 Ward Services"}]', 5, '2026-08-03 06:53:49.391619+00', '2026-08-03 07:13:16.330168+00'),
	('9a4f685f-525e-4ca0-9747-8deacac44480', '324446de-b73e-4d80-9808-cf922015153b', 'Imaging & Diagnostics', '', '["Ultrasound Services", "CT Scan Services", "X-RAY Services (Chest, Extremities, Head, Spine, Pelvic, and Abdomen)", {"items": ["Chest X-ray (AP, PA, Lateral, Apicolordotic, Decubitus)", "Abdomen X-ray (Flat, Upright)", "K.U.B. AP"], "title": "Standard Chest & Abdomen X-Rays"}, {"items": ["Hand (APL, APO)", "Wrist (APL)", "Forearm (APL) & Arm (APL)", "Elbow (APL)", "Shoulder (AP, Scapular Y)", "Clavicle AP", "Hip AP & Pelvis AP", "Thigh (APL) & Leg (APL)", "Knee (APL)", "Ankle (APL, Mortise View)", "Foot (APO, APL)"], "title": "Extremity & Joint X-Rays"}, {"items": ["Skull (APL, Towne''s, Water''s, Caldwell''s View)", "Cervical APL", "Mandible Ribs (APO, AP, Lateral, Oblique)", "Thoracic Spine (AP, Lateral)", "Thoraco-Lumbar (AP, Lateral)", "Lumbo-Sacral (AP, Lateral)", "Nasal Bone Lateral & Paranasal Sinuses"], "title": "Head, Neck & Spine X-Rays"}]', 3, '2026-08-03 06:53:49.391619+00', '2026-08-03 07:13:16.330168+00'),
	('03f71c6b-22eb-419e-ac95-02e432d26614', '324446de-b73e-4d80-9808-cf922015153b', 'Special Programs & Counseling', '', '["Accredited Drug Testing Center", {"items": ["Drug Dependency Evaluation", "Community Based Rehabilitation Program Without Walls", "Matrix Intensive Outpatient Program", "Community Service & Tree Growing Initiatives", "Physical & Spiritual Wellness Activities", "Drug Test Administration", "Aftercare and Social Support Group Sessions", "Family Counseling Sessions", "Drug Symposiums (Suspended due to pandemic)"], "title": "Center for Drug Education & Counseling (CEDEC)"}, {"items": ["Patient PhilHealth Classification Assessments", "Medical Assistance to Indigent Patients (MAIP) Provision", "No Balance Billing (NBB) Policy Implementations"], "title": "Medical Social Work Services"}]', 6, '2026-08-03 06:53:49.391619+00', '2026-08-03 07:13:16.330168+00'),
	('d873691c-2b34-4e84-8174-f5ab271043c1', 'd98ef878-4088-41ce-85e7-4a4304b7dbfa', 'Emergency', '', '["24/7 ER services"]', 2, '2026-08-03 06:53:49.391619+00', '2026-08-05 06:29:45.5769+00'),
	('5ed29b29-22b3-4f0f-a9a4-dde2799401b3', 'd98ef878-4088-41ce-85e7-4a4304b7dbfa', 'Outpatient', '', '["Consultations", "Prenatal and follow-up care service"]', 3, '2026-08-03 06:53:49.391619+00', '2026-08-05 06:29:45.5769+00'),
	('ad335805-90bd-4e42-89ef-51f1ab33c708', 'd98ef878-4088-41ce-85e7-4a4304b7dbfa', 'Inpatient', '', '["Hospital admission and nursing care service"]', 4, '2026-08-03 06:53:49.391619+00', '2026-08-05 06:29:45.5769+00'),
	('4fa9ef5f-63b3-490d-a66d-775ef6605c6f', 'd98ef878-4088-41ce-85e7-4a4304b7dbfa', 'Imaging', '', '["Basic X-ray services", "Ultrasound Services", "Dispensing medicines"]', 6, '2026-08-03 06:53:49.391619+00', '2026-08-05 06:29:45.5769+00');
