INSERT INTO "public"."page_sections" ("id", "page_name", "section_key", "title", "content", "created_at", "updated_at") VALUES
	('d50dc331-325c-4e73-83b3-ae6f86fa9148', 'about', 'history', 'About History', '{"paragraphs": ["The health services in the Province of Bohol were first introduced by the Department of Health in mid-1959 through the Maternal Child Health Care Program. The main thrust at the time was the Expanded Program on Immunization and Tuberculosis Program.", "In the early 1960s, the Provincial Government supplemented manpower by creating the Provincial Health Office. Personnel included Sanitary Inspectors, Medical Technologists, Dentists, and Administrative Staff. Over the following decades, operations transitioned from centralization to decentralization, culminating in the integration of health services in 1983.", "By 1991, through the Local Government Code, health services were devolved to the local government units. Despite initial financial struggles, the Provincial Government worked tirelessly to elevate devolved hospitals to competitive standards, procuring modern equipment and executing rehabilitation projects to deliver quality healthcare to every Boholano."]}', '2026-07-30 01:59:45.580978+00', '2026-07-30 01:59:45.580978+00'),
	('83dcfdf9-9303-4849-a3f3-ac5502541bb7', 'about', 'strategies', 'About Strategies', '{"slides": [{"title": "Capability-building", "image_url": "assets/about/strat-capability.png"}, {"title": "Networking & Linkaging", "image_url": "assets/about/strat-networking.png"}, {"title": "Social Marketing", "image_url": "assets/about/strat-social.png"}, {"title": "Upgrading Health Services", "image_url": "assets/about/strat-upgrading.png"}, {"title": "Innovative Health Programs", "image_url": "assets/about/strat-innovative.png"}, {"title": "Enterprise Development", "image_url": "assets/about/strat-enterprise.png"}, {"title": "Health Information System", "image_url": "assets/about/strat-infosystem.png"}, {"title": "Income Retention Scheme", "image_url": "assets/about/strat-retention.png"}]}', '2026-07-30 01:59:45.580978+00', '2026-07-30 01:59:45.580978+00'),
	('fd64adeb-ae1e-4518-95ce-886d0d78b6f5', 'shared', 'footer', 'Footer', '{"phone": "(038) 411 0138 · Local: 41107", "title": "Bohol Provincial Health Office", "emails": ["pho_bohol@yahoo.com", "provincialhealthoffice@gmail.com"], "subtitle": "Province of Bohol, Philippines", "copyright": "© 2026 Bohol Provincial Health Office. All Rights Reserved.", "description": "The frontline agency of the Provincial Government of Bohol mandated to deliver quality healthcare services to every Boholano.", "quick_links": [{"url": "index.html", "label": "Home"}, {"url": "more-about-us.html", "label": "About"}, {"url": "index.html#services", "label": "Services"}, {"url": "laboratory.html", "label": "Laboratory & Facilities"}, {"url": "promotive.html", "label": "Promotive & Preventive"}, {"url": "hospitals.html", "label": "Hospitals"}], "facebook_url": "https://www.facebook.com/boholpho", "facebook_label": "Bohol Provincial Health Office", "government_links": [{"url": "https://bohol.gov.ph", "label": "Province of Bohol"}, {"url": "https://doh.gov.ph", "label": "Dept. of Health"}, {"url": "https://www.gov.ph", "label": "GOV.PH"}, {"url": "https://philhealth.gov.ph", "label": "PhilHealth"}, {"url": "https://fda.gov.ph", "label": "FDA Philippines"}]}', '2026-07-30 01:59:45.580978+00', '2026-08-03 06:06:31.613156+00'),
	('112b3f0e-84c8-45bf-8f04-75c25dd11342', 'home', 'hero', 'Home Hero', '{"slides": [{"alt": "Bohol Provincial Health Office Building", "image_url": "assets/hero/hero-1.jpg"}, {"alt": "Bohol Provincial Health Office", "image_url": "assets/hero/hero-2.jpg"}, {"alt": "Water Testing Laboratory", "image_url": "assets/hero/hero-3.jpg"}, {"alt": "Bohol Provincial Diagnostic and Ambulatory Care Center", "image_url": "assets/hero/hero-4.jpg"}], "tagline": "Sa PHO, Una ang Serbisyo!", "welcome": "Welcome To", "heading_html": "Bohol Provincial<br><em>Health Office</em>"}', '2026-07-30 01:59:45.580978+00', '2026-07-30 04:54:10.722393+00'),
	('af7d68e0-5dc4-4771-9004-282616c65828', 'home', 'about', 'Home About Block', '{"body": "The Bohol Provincial Health Office (PHO) is the frontline agency of the Provincial Government of Bohol mandated to deliver quality healthcare services to every Boholano. Guided by our Vision, Mission, and Goals, we strive for a healthy and self-reliant community.", "heading": "About Us", "button_url": "more-about-us.html", "button_label": "Explore More About Us →"}', '2026-07-30 01:59:45.580978+00', '2026-07-30 02:32:04.243984+00'),
	('e8ddbcbd-5281-45e2-9560-9a866e2a384b', 'about', 'hero', 'About Hero', '{"title": "About Us", "subtitle": "Guided by our Vision, Mission, and Goals, we strive for a healthy and self-reliant Boholano community.", "background_image_url": "assets/about/hero.jpg"}', '2026-07-30 01:59:45.580978+00', '2026-07-30 02:37:02.54754+00'),
	('b5ee1149-1f54-480d-9a97-59f395407589', 'shared', 'navbar', 'Navbar', '{"title": "Bohol Provincial Health Office", "subtitle": "Province of Bohol, Philippines", "home_href": "", "home_label": ""}', '2026-07-30 01:39:19.819577+00', '2026-08-04 04:08:02.984847+00'),
	('7059f893-b4f1-4840-8a3b-af7924b9623c', 'about', 'org_structure', 'Organizational Structure', '{"images": [{"alt": "PHO Organizational Structure - Part 1", "caption": "Page 1 of 13", "image_url": "assets/about/org1.png"}, {"alt": "PHO Organizational Structure - Part 2", "caption": "Page 2 of 13", "image_url": "assets/about/org2.png"}, {"alt": "PHO Organizational Structure - Part 3", "caption": "Page 3 of 13", "image_url": "assets/about/org3.png"}, {"alt": "PHO Organizational Structure - Part 4", "caption": "Page 4 of 13", "image_url": "assets/about/org4.png"}, {"alt": "PHO Organizational Structure - Part 5", "caption": "Page 5 of 13", "image_url": "assets/about/org5.png"}, {"alt": "PHO Organizational Structure - Part 6", "caption": "Page 6 of 13", "image_url": "assets/about/org6.png"}, {"alt": "PHO Organizational Structure - Part 7", "caption": "Page 7 of 13", "image_url": "assets/about/org7.png"}, {"alt": "PHO Organizational Structure - Part 8", "caption": "Page 8 of 13", "image_url": "assets/about/org8.png"}, {"alt": "PHO Organizational Structure - Part 9", "caption": "Page 9 of 13", "image_url": "assets/about/org9.png"}, {"alt": "PHO Organizational Structure - Part 10", "caption": "Page 10 of 13", "image_url": "assets/about/org10.png"}, {"alt": "PHO Organizational Structure - Part 11", "caption": "Page 11 of 13", "image_url": "assets/about/org11.png"}, {"alt": "PHO Organizational Structure - Part 12", "caption": "Page 12 of 13", "image_url": "assets/about/org12.png"}, {"alt": "PHO Organizational Structure - Part 13", "caption": "Page 13 of 13", "image_url": "assets/about/org13.png"}]}', '2026-07-30 01:59:45.580978+00', '2026-07-30 01:59:45.580978+00'),
	('e7f1efee-2f07-4f63-84e4-2c12b4729182', 'home', 'services', 'Home Services', '{"cards": [{"url": "laboratory.html", "theme": "lab", "icon_key": "lab", "back_title": "Laboratory & Health Facilities", "button_label": "VIEW DETAILS ->", "back_description": "Provincial diagnostic labs, cold chain facility, water bacteriology, drug testing, PCR laboratory, dialysis centers, and wellness centers serving the province.", "front_title_html": "Laboratory &amp; Other<br>Health Facilities"}, {"url": "promotive.html", "theme": "promo", "icon_key": "promo", "back_title": "Promotive & Preventive Services", "button_label": "VIEW DETAILS ->", "back_description": "Health education, epidemiology & surveillance, disaster risk reduction, nutrition, oral health, vaccination programs, and community-based health initiatives.", "front_title_html": "Promotive &amp; Preventive<br>Health Services"}, {"url": "hospitals.html", "theme": "hosp", "icon_key": "hospital", "back_title": "Hospital Services", "button_label": "VIEW DETAILS ->", "back_description": "Nine provincial hospitals across Bohol providing comprehensive medical care — from general medicine to specialized services for every district.", "front_title_html": "Hospital<br>Services"}]}', '2026-07-30 01:59:45.580978+00', '2026-07-30 02:31:35.492835+00'),
	('afb7dc62-3e74-4886-80c1-3335af9f447f', 'promotive', 'hero', 'Promotive Hero', '{"title": "Promotive & Preventive Health Services", "subtitle": "Community health programs focused on disease prevention and wellness promotion"}', '2026-07-30 01:59:45.580978+00', '2026-07-30 05:08:34.584391+00'),
	('c58b1709-d081-4793-adae-604ded199c0d', 'about', 'units', 'About Sections & Units', '{"cards": [{"title": "Budget & Finance", "image_url": "assets/about/unit-finance.png", "back_title": "Budget & Finance", "description": "Manages financial allocations, budgets for health programs and hospitals, medical procurement, payroll, and auditing compliance to support frontline healthcare services."}, {"title": "Human Resources Development", "image_url": "assets/about/unit-hr.png", "back_title": "Human Resources", "description": "Recruits, trains, and supports our healthcare workforce. Manages personnel onboarding, continuous training, and evaluations to deliver quality public health services."}, {"title": "Records & Communications", "image_url": "assets/about/unit-records.png", "back_title": "Records & Comm", "description": "Manages official documentation, inter-office correspondence, and public health records while ensuring data privacy compliance and efficient information flow."}, {"title": "Supplies & Gen. Services", "image_url": "assets/about/unit-supplies.png", "back_title": "Supplies & Services", "description": "Manages procurement, storage, and distribution of medical assets and supplies. Coordinates facility maintenance, security, and the ambulance/vehicle fleet."}]}', '2026-07-30 01:59:45.580978+00', '2026-07-30 02:38:56.455932+00'),
	('cc082761-46f9-433f-aab8-3e22f4e090f3', 'contact', 'info', 'Contact Info & Form', '{"emails": ["pho_bohol@yahoo.com", "provincialhealthoffice@gmail.com"], "address": "Purok 7", "form_title": "Send a Message", "phone_html": "Primary: (038) 411 0138<br>Local Admin: 41107<br>Local Health Office: 41034", "email_heading": "Email Address", "form_subtitle": "Have a question or feedback? Complete this form to email us directly.", "hours_heading": "Office Hoursss", "phone_heading": "Phone Numbers", "location_heading": "Our Location", "office_hours_html": "Monday - Friday: 8:00 AM - 5:00 PM<br>(Except Weekends &amp; Holidays)"}', '2026-07-30 01:59:45.580978+00', '2026-07-30 08:19:52.355704+00'),
	('389935e5-fad2-4143-af9b-600bc8cf3b17', 'laboratory', 'hero', 'Laboratory Hero', '{"title": "Laboratory & Other Health Facilities", "subtitle": "Provincial diagnostic laboratories, treatment centers, and specialized health facilities", "background_image_url": ""}', '2026-07-30 01:59:45.580978+00', '2026-07-30 05:07:20.663277+00'),
	('4cedac07-874f-4fc6-9f3b-c83f2da4671c', 'hospitals', 'hero', 'Hospitals Hero', '{"title": "Hospital Services", "subtitle": "Ten provincial hospitals delivering comprehensive medical care across Bohol"}', '2026-07-30 01:59:45.580978+00', '2026-08-03 07:08:09.96454+00'),
	('aef946e5-7999-4743-9890-d711ebe00bf6', 'contact', 'hero', 'Contact Hero', '{"title": "Contact Us", "subtitle": "We are here to assist you. Reach out to the Bohol Provincial Health Office through our dynamic channels, directory, or submit an online inquiry below.", "background_image_url": ""}', '2026-07-30 01:59:45.580978+00', '2026-07-30 08:10:26.541175+00'),
	('bc7a7f63-abc0-4e38-9b70-5be27a5d8d73', 'home', 'vmg', 'Vision, Mission, Goals', '{"items": [{"title": "Vision", "body_html": "A responsive and dynamic health organization committed to provide the best quality services with skilled, competent and effective personnel geared towards healthy and self-reliant Boholano community."}, {"title": "Mission", "body_html": "To ensure and safeguard the health of the Boholano community through effective and sustainable delivery of promotive, preventive, curative and rehabilitative health services in partnership with all stakeholders for a productive Boholano."}, {"title": "Goals", "body_html": "<ul><li>To provide available, affordable and accessible basic health services</li><li>To reduce morbidity and mortality rate</li><li>To upgrade and strengthen hospital services</li><li>To modernize and maintain hospital equipment and facilities</li><li>To sustain high ethical standards among health personnel</li><li>To enhance the technical capability of health personnel</li><li>To provide technical assistance to other stakeholders</li><li>To strengthen the Health Information System(HIS)</li><li>To build sustainable networking with other community health providers</li><li>To enhance public enterprise to generate resources</li></ul>"}]}', '2026-07-30 01:59:45.580978+00', '2026-07-30 02:32:42.810125+00');
